import csv
from pathlib import Path

from pydantic import BaseModel, Field

from .config import FOODS_CSV_PATH

# Classify comma-separated CSV suffixes that already exist. Not a list of extra foods.
_COOKING_MARKERS = (
    "cooked",
    "grilled",
    "boiled",
    "scrambled",
    "canned",
    "raw",
    "sautéed",
    "sauteed",
    "fried",
    "baked",
    "roasted",
    "steamed",
)


class FoodRow(BaseModel):
    name: str = Field(min_length=1)
    kcal_per_100g: float
    protein_g: float
    carbs_g: float
    fat_g: float
    source: str


class FoodParts(BaseModel):
    name: str
    base: str
    color: str | None = None
    prep: str | None = None


def load_foods(path: Path | None = None) -> dict[str, FoodRow]:
    """Load the reference table keyed by exact CSV name (the prompt list)."""
    csv_path = path or FOODS_CSV_PATH
    foods: dict[str, FoodRow] = {}
    with csv_path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            food = FoodRow.model_validate(row)
            foods[food.name] = food
    if not foods:
        raise ValueError(f"No foods loaded from {csv_path}")
    return foods


def food_names(foods: dict[str, FoodRow] | None = None) -> list[str]:
    table = foods if foods is not None else load_foods()
    return list(table.keys())


def get_food(name: str, foods: dict[str, FoodRow]) -> FoodRow | None:
    """Exact CSV name only. Callers mark a miss as unknown."""
    return foods.get(name)


def _is_cooking_part(part: str) -> bool:
    lowered = part.lower()
    return any(marker in lowered for marker in _COOKING_MARKERS)


def parse_food_name(name: str) -> FoodParts:
    parts = [piece.strip() for piece in name.split(",") if piece.strip()]
    base = parts[0]
    color = None
    prep = None
    for part in parts[1:]:
        if _is_cooking_part(part):
            prep = part
        else:
            color = part
    return FoodParts(name=name, base=base, color=color, prep=prep)


def match_csv_name(
    base: str,
    foods: dict[str, FoodRow],
    color: str | None = None,
    prep: str | None = None,
) -> str | None:
    """Return the exact CSV name for this combination, or None if it is not in the table."""
    color_key = color or None
    prep_key = prep or None
    matches = []
